mapper.select:
/* boardInqyDao1020 : 공지사항 목록 조회 */ SELECT SUB_DATA.NUM , SUB_DATA.BRD_ID , SUB_DATA.BRD_TITLE , SUB_DATA.EMP_NM , SUB_DATA.ORG_NM , SUB_DATA.RANK_NM , SUB_DATA.LIST_CNT , SUB_DATA.REG_DT , SUB_DATA.READ_HIT , CASE WHEN SUB_DATA.FILE_CNT > 0 THEN 'Y' ELSE 'N' END AS FILE_YN , SUB_DATA.USE_YN FROM ( SELECT B.BRD_ID , B.BRD_TITLE , B.EMP_IDX , E.EMP_NM , O.ORG_NM , R.RANK_NM , TO_CHAR(B.REG_DT, 'YYYYMMDD') AS REG_DT , B.READ_HIT , ROW_NUMBER() OVER(ORDER BY B.REG_DT DESC, B.BRD_ID DESC) AS NUM , COUNT(B.BRD_ID) OVER() AS LIST_CNT , (SELECT COUNT(*) FROM FILE_INFO F WHERE F.FILE_ID = B.FILE_ID AND F.USE_YN = 'Y') AS FILE_CNT , B.USE_YN FROM BOARD B LEFT OUTER JOIN EMP_INFO E ON B.EMP_IDX = E.EMP_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD AND O.USE_YN = 'Y' LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD AND R.USE_YN = 'Y' WHERE B.USE_YN = 'Y'
AND REGEXP_REPLACE(LOWER(B.BRD_TITLE), '[^0-9가-힣A-Za-z]', '') LIKE '%' || REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]', '') || '%'
AND B.REG_DT >= TO_DATE(#{srchSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
AND B.REG_DT < TO_DATE(#{srchEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1
AND REGEXP_REPLACE(LOWER(O.ORG_NM), '[^0-9가-힣A-Za-z]', '') LIKE '%' || REGEXP_REPLACE(LOWER(#{orgNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]', '') || '%'
AND REGEXP_REPLACE(LOWER(R.RANK_NM), '[^0-9가-힣A-Za-z]', '') LIKE '%' || REGEXP_REPLACE(LOWER(#{rankNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]', '') || '%'
AND REGEXP_REPLACE(LOWER(E.EMP_NM), '[^0-9가-힣A-Za-z]', '') LIKE '%' || REGEXP_REPLACE(LOWER(#{srchIdx, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]', '') || '%'
) SUB_DATA WHERE 1 = 1
AND SUB_DATA.NUM BETWEEN #{sIdx, jdbcType=VARCHAR} AND #{eIdx, jdbcType=VARCHAR}
ORDER BY SUB_DATA.NUM ASC

mapper.insert:
	/* boardProcDao1010 : 공지사항 등록 처리 */
	INSERT INTO BOARD
    (
        	BRD_ID
        , 	EMP_IDX
        , 	BRD_TITLE
        , 	BRD_CONT
        , 	READ_HIT
        , 	FILE_ID
        , 	REG_IDX
        , 	REG_DT
        , 	USE_YN
        , 	DISP_ORDER
        , 	REMARK
    )
    VALUES
    (
        	(SELECT 'BRD_' || LPAD(NVL(MAX(REPLACE(BRD_ID,'BRD_')),0) + 1,4,0) AS BRD_ID FROM BOARD)
        , 	#{empIdx, jdbcType=VARCHAR}
        , 	#{brdTitle, jdbcType=VARCHAR}
        , 	#{brdCont, jdbcType=CLOB}
        , 	0
        , 	#{fileId, jdbcType=VARCHAR}
        , 	#{regIdx, jdbcType=VARCHAR}
        , 	SYSDATE
        , 	#{useYn, jdbcType=VARCHAR}
        , 	(
            	SELECT NVL(MAX(DISP_ORDER), 0) + 1
            	FROM BOARD
        	)
        , 	NULL
    )

