	/* boardProcDao1040 : 공지사항 수정 처리 */
	UPDATE BOARD
    	SET BRD_TITLE = #{brdTitle, jdbcType=VARCHAR}
        	, 	BRD_CONT = #{brdCont, jdbcType=CLOB}
        	, 	FILE_ID = #{fileId, jdbcType=VARCHAR}
        	, 	USE_YN = #{useYn, jdbcType=VARCHAR}
        	, 	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
        	, 	MOD_DT = SYSDATE
    WHERE BRD_ID = #{brdId, jdbcType=VARCHAR}

/* boardProcDao1050 : 공지사항 조회수 증가 */
UPDATE BOARD
	SET 	READ_HIT = READ_HIT + 1
WHERE BRD_ID = #{brdId, jdbcType=VARCHAR}
